        [f"Ghi tên xã/phường hiện tại thuộc {name}.","Bổ sung đường, số nhà, thôn/tổ/khu vực hoặc mốc gần vị trí cần lắp.","Nếu giấy tờ cũ dùng tên đơn vị cấp xã trước thay đổi, có thể ghi thêm trong phần ghi chú.","Nêu số tầng, số thiết bị và nhu cầu chính trước khi đối chiếu gói và thiết bị."],
