def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--site", required=True)
    args = parser.parse_args()
    target = Path(args.site) / "khu-vuc"
    target.mkdir(parents=True, exist_ok=True)
    for idx, loc in enumerate(LOCATIONS):
        out = target / loc["slug"] / "index.html"
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(render_page(loc, idx), encoding="utf-8")
    (target / "index.html").write_text(render_index(), encoding="utf-8")
    print(f"Local pages generated: {len(LOCATIONS)} + index")


if __name__ == "__main__":
    main()
